#!/bin/bash
# Generated by reef-eval's EdgeBench converter. Runs in the SEPARATE verifier
# container (built from the judge image). Harbor re-materializes the declared
# submission artifacts at their original paths before this script runs; the
# checks below just make a missing submission loud.
set -uo pipefail
mkdir -p /logs/verifier

[ -e "/home/workspace/zig-port/." ] || echo "WARNING: submission missing: /home/workspace/zig-port/."

cd /home/workspace/zig-port
OUT=$(mkdir -p /logs/verifier /tmp/verifier && ln -sfn /home/workspace /app && ln -sfn /opt/tests /tests && ln -sfn /tmp/verifier /logs/verifier 2>/dev/null; export APP_DIR=/home/workspace VERIFIER_DIR=/logs/verifier && bash /opt/tests/test.sh >/tmp/verifier.log 2>&1 || true; cat /tmp/verifier.log >&2; bash /opt/tests/pytest_shim.sh "/logs/verifier/reward.json" 2>&1)
EC=$?
echo "$OUT" | tail -40
printf '%s' "$OUT" | python3 /tests/parse_score.py
echo "eval exit code: $EC" > /logs/verifier/eval_exit_code.txt
